"""Lexer and recursive-descent parser for minisql's SELECT subset."""
from dataclasses import dataclass


@dataclass(frozen=True)
class Expr:
    """Expression node. ``kind`` is one of literal/column/unary/binary/
    is_null/in/between/like/call; ``raw`` preserves its query spelling."""
    kind: str
    value: object = None
    args: tuple = ()
    raw: str = ""
    source_start: int = -1


@dataclass(frozen=True)
class Star:
    """The special star argument to COUNT, or a wildcard select item."""


@dataclass(frozen=True)
class SelectItem:
    expr: Expr
    alias: object = None


@dataclass(frozen=True)
class OrderItem:
    expr: Expr
    descending: bool = False


@dataclass(frozen=True)
class Query:
    distinct: bool
    columns: tuple
    table: str
    where: object = None
    group_by: tuple = ()
    having: object = None
    order_by: tuple = ()
    limit: object = None
    offset: int = 0


class ParseError(ValueError):
    """Invalid SQL syntax."""


KEYWORDS = {
    "SELECT", "DISTINCT", "FROM", "WHERE", "GROUP", "BY", "HAVING",
    "ORDER", "ASC", "DESC", "LIMIT", "OFFSET", "AS", "AND", "OR",
    "NOT", "IN", "BETWEEN", "LIKE", "IS", "NULL", "TRUE", "FALSE",
}


@dataclass(frozen=True)
class Token:
    kind: str
    value: object
    start: int
    end: int


def _lex(sql):
    out = []
    i, n = 0, len(sql)
    while i < n:
        c = sql[i]
        if c.isspace():
            i += 1
            continue
        start = i
        if c == "'":
            i += 1
            chars = []
            while i < n:
                if sql[i] == "'":
                    if i + 1 < n and sql[i + 1] == "'":
                        chars.append("'")
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    chars.append(sql[i])
                    i += 1
            else:
                raise ParseError("unterminated string literal")
            out.append(Token("LITERAL", "".join(chars), start, i))
            continue
        if c == '"':
            i += 1
            chars = []
            while i < n:
                if sql[i] == '"':
                    if i + 1 < n and sql[i + 1] == '"':
                        chars.append('"')
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    chars.append(sql[i])
                    i += 1
            else:
                raise ParseError("unterminated quoted name")
            out.append(Token("IDENT", "".join(chars), start, i))
            continue
        if c.isdigit() or (c == "." and i + 1 < n and sql[i + 1].isdigit()):
            j = i
            while j < n and sql[j].isdigit():
                j += 1
            decimal = False
            if j < n and sql[j] == ".":
                decimal = True
                j += 1
                while j < n and sql[j].isdigit():
                    j += 1
            text = sql[i:j]
            val = float(text) if decimal else int(text)
            out.append(Token("LITERAL", val, start, j))
            i = j
            continue
        if c.isalpha() or c == "_":
            i += 1
            while i < n and (sql[i].isalnum() or sql[i] == "_"):
                i += 1
            word = sql[start:i]
            upper = word.upper()
            if upper in ("NULL", "TRUE", "FALSE"):
                val = {"NULL": None, "TRUE": True, "FALSE": False}[upper]
                out.append(Token("LITERAL", val, start, i))
            elif upper in KEYWORDS:
                out.append(Token("KW", upper, start, i))
            else:
                out.append(Token("IDENT", word, start, i))
            continue
        two = sql[i:i + 2]
        if two in ("!=", "<>", "<=", ">=", "||"):
            out.append(Token("OP", two, i, i + 2))
            i += 2
            continue
        if c in "=<>+-*/(),;":
            out.append(Token("PUNC" if c in "(),;" else "OP", c, i, i + 1))
            i += 1
            continue
        raise ParseError("unexpected character %r at position %d" % (c, i))
    out.append(Token("EOF", None, n, n))
    return out


class _Parser:
    def __init__(self, sql):
        self.sql = sql
        self.tokens = _lex(sql)
        self.i = 0

    @property
    def t(self):
        return self.tokens[self.i]

    def take(self):
        t = self.t
        self.i += 1
        return t

    def is_kw(self, word):
        return self.t.kind == "KW" and self.t.value == word

    def accept_kw(self, word):
        if self.is_kw(word):
            return self.take()
        return None

    def accept(self, value):
        if self.t.value == value:
            return self.take()
        return None

    def expect_kw(self, word):
        if not self.accept_kw(word):
            self.fail("expected " + word)

    def expect(self, value):
        if not self.accept(value):
            self.fail("expected %r" % value)

    def fail(self, message):
        raise ParseError("%s at position %d" % (message, self.t.start))

    def identifier(self):
        if self.t.kind != "IDENT":
            self.fail("expected name")
        return self.take().value

    def parse(self):
        self.expect_kw("SELECT")
        distinct = bool(self.accept_kw("DISTINCT"))
        columns = []
        if self.accept("*"):
            columns.append(Star())
        else:
            while True:
                expr = self.expression()
                alias = None
                if self.accept_kw("AS"):
                    alias = self.identifier()
                elif self.t.kind == "IDENT":
                    alias = self.take().value
                columns.append(SelectItem(expr, alias))
                if not self.accept(","):
                    break
        self.expect_kw("FROM")
        table = self.identifier()
        where = self.expression() if self.accept_kw("WHERE") else None
        group = []
        if self.accept_kw("GROUP"):
            self.expect_kw("BY")
            group.append(self.expression())
            while self.accept(","):
                group.append(self.expression())
        having = self.expression() if self.accept_kw("HAVING") else None
        order = []
        if self.accept_kw("ORDER"):
            self.expect_kw("BY")
            while True:
                e = self.expression()
                descending = bool(self.accept_kw("DESC"))
                if not descending:
                    self.accept_kw("ASC")
                order.append(OrderItem(e, descending))
                if not self.accept(","):
                    break
        limit = offset = None
        if self.accept_kw("LIMIT"):
            if self.t.kind != "LITERAL" or isinstance(self.t.value, (str, bool)) or self.t.value is None or not isinstance(self.t.value, int):
                self.fail("LIMIT requires a non-negative integer")
            limit = self.take().value
            if limit < 0:
                self.fail("LIMIT requires a non-negative integer")
            if self.accept_kw("OFFSET"):
                if self.t.kind != "LITERAL" or not isinstance(self.t.value, int) or isinstance(self.t.value, bool) or self.t.value < 0:
                    self.fail("OFFSET requires a non-negative integer")
                offset = self.take().value
            else:
                offset = 0
        self.accept(";")
        if self.t.kind != "EOF":
            self.fail("unexpected token")
        return Query(distinct, tuple(columns), table, where, tuple(group), having,
                     tuple(order), limit, 0 if offset is None else offset)

    def expression(self):
        return self._or()

    def _node(self, kind, value, args, start):
        end = self.tokens[self.i - 1].end
        return Expr(kind, value, tuple(args), self.sql[start:end], start)

    def _or(self):
        left = self._and()
        while self.accept_kw("OR"):
            start = self._start(left)
            right = self._and()
            left = self._node("binary", "OR", (left, right), start)
        return left

    def _and(self):
        left = self._not()
        while self.accept_kw("AND"):
            start = self._start(left)
            right = self._not()
            left = self._node("binary", "AND", (left, right), start)
        return left

    def _not(self):
        if self.is_kw("NOT"):
            tok = self.take()
            child = self._not()
            return self._node("unary", "NOT", (child,), tok.start)
        return self._comparison()

    def _comparison(self):
        left = self._concat()
        negated = False
        if self.is_kw("NOT") and self.tokens[self.i + 1].value in ("IN", "BETWEEN", "LIKE"):
            self.take()
            negated = True
        if self.accept_kw("IS"):
            neg = bool(self.accept_kw("NOT"))
            self.expect_kw("NULL")
            return self._node("is_null", neg, (left,), self._start(left))
        if self.accept_kw("IN"):
            self.expect("(")
            if self.accept(")"):
                self.fail("IN list cannot be empty")
            items = [self.expression()]
            while self.accept(","):
                items.append(self.expression())
            self.expect(")")
            return self._node("in", negated, (left, *items), self._start(left))
        if self.accept_kw("BETWEEN"):
            low = self._concat()
            self.expect_kw("AND")
            high = self._concat()
            return self._node("between", negated, (left, low, high), self._start(left))
        if self.accept_kw("LIKE"):
            pattern = self._concat()
            return self._node("like", negated, (left, pattern), self._start(left))
        if negated:
            self.fail("expected IN, BETWEEN, or LIKE after NOT")
        if self.t.kind == "OP" and self.t.value in ("=", "!=", "<>", "<", "<=", ">", ">="):
            op = self.take()
            right = self._concat()
            return self._node("binary", op.value, (left, right), self._start(left))
        return left

    def _concat(self):
        left = self._sum()
        while self.accept("||"):
            start = self._start(left)
            right = self._sum()
            left = self._node("binary", "||", (left, right), start)
        return left

    def _sum(self):
        left = self._product()
        while self.t.value in ("+", "-") and self.t.kind == "OP":
            op = self.take().value
            right = self._product()
            left = self._node("binary", op, (left, right), self._start(left))
        return left

    def _product(self):
        left = self._unary()
        while self.t.value in ("*", "/") and self.t.kind == "OP":
            op = self.take().value
            right = self._unary()
            left = self._node("binary", op, (left, right), self._start(left))
        return left

    def _unary(self):
        if self.t.value == "-" and self.t.kind == "OP":
            tok = self.take()
            child = self._unary()
            return self._node("unary", "-", (child,), tok.start)
        return self._primary()

    def _primary(self):
        tok = self.t
        if tok.kind == "LITERAL":
            self.take()
            return Expr("literal", tok.value, (), self.sql[tok.start:tok.end], tok.start)
        if tok.kind == "IDENT":
            name = self.take().value
            if self.accept("("):
                args = []
                if not self.accept(")"):
                    if self.accept("*"):
                        args.append(Star())
                        self.expect(")")
                    else:
                        args.append(self.expression())
                        while self.accept(","):
                            args.append(self.expression())
                        self.expect(")")
                return self._node("call", name, args, tok.start)
            return Expr("column", name, (), self.sql[tok.start:tok.end], tok.start)
        if self.accept("("):
            start = tok.start
            e = self.expression()
            self.expect(")")
            # Preserve parentheses for expression-derived output labels.
            return Expr(e.kind, e.value, e.args, self.sql[start:self.tokens[self.i - 1].end], start)
        self.fail("expected expression")

    def _start(self, expr):
        # Find source position for a previously assembled child expression.
        return expr.source_start


def parse(sql):
    """Parse one query and return a :class:`Query`; raises ParseError."""
    return _Parser(sql).parse()
"""Expression evaluation and SQL value semantics for minisql."""
import re
from decimal import Decimal, ROUND_HALF_UP

from . import QueryError

AGGREGATES = {"COUNT", "SUM", "AVG", "MIN", "MAX"}


def contains_aggregate(expr):
    if expr is None:
        return False
    if getattr(expr, "kind", None) == "call" and str(expr.value).upper() in AGGREGATES:
        return True
    return any(contains_aggregate(a) for a in getattr(expr, "args", ()) if getattr(a, "kind", None))


def _has_aggregate_call(expr):
    return getattr(expr, "kind", None) == "call" and str(expr.value).upper() in AGGREGATES or any(
        _has_aggregate_call(a) for a in getattr(expr, "args", ()) if getattr(a, "kind", None))


def validate_aggregates(expr, allow=True):
    """Raise QueryError for aggregates in forbidden positions or nesting."""
    if getattr(expr, "kind", None) == "call" and str(expr.value).upper() in AGGREGATES:
        if not allow:
            raise QueryError("aggregates are not allowed here")
        if any(_has_aggregate_call(a) for a in expr.args if getattr(a, "kind", None)):
            raise QueryError("aggregate functions cannot be nested")
    for a in getattr(expr, "args", ()):
        if getattr(a, "kind", None):
            validate_aggregates(a, allow)


def _truth(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return v
    raise QueryError("logical operators require boolean values")


def _numeric(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def _compare_type(a, b):
    if isinstance(a, bool) or isinstance(b, bool):
        if isinstance(a, bool) and isinstance(b, bool):
            return
        raise QueryError("incompatible values for comparison")
    if _numeric(a) and _numeric(b) or isinstance(a, str) and isinstance(b, str):
        return
    raise QueryError("incompatible values for comparison")


def _cmp(a, b, op):
    _compare_type(a, b)
    try:
        return {"=": lambda: a == b, "!=": lambda: a != b, "<>": lambda: a != b,
                "<": lambda: a < b, "<=": lambda: a <= b, ">": lambda: a > b,
                ">=": lambda: a >= b}[op]()
    except (TypeError, KeyError):
        raise QueryError("invalid comparison")


def _arithmetic(op, a, b):
    if a is None or b is None:
        return None
    if op == "||":
        return str(a) + str(b)
    if not _numeric(a) or not _numeric(b):
        raise QueryError("arithmetic requires numeric values")
    if op == "/":
        return None if b == 0 else float(a) / float(b)
    return {"+": lambda: a + b, "-": lambda: a - b, "*": lambda: a * b}[op]()


def _column(row, name):
    if row is None:
        raise QueryError("column is unavailable in this expression")
    if name in row:
        return row[name]
    for key, value in row.items():
        if str(key).casefold() == str(name).casefold():
            return value
    raise QueryError("unknown column: " + str(name))


def _round_away(x, n):
    if not _numeric(x):
        raise QueryError("ROUND requires a numeric value")
    try:
        result = Decimal(str(x)).quantize(Decimal(1).scaleb(-n), rounding=ROUND_HALF_UP)
        return int(result) if n == 0 else float(result)
    except Exception as e:
        raise QueryError("invalid ROUND precision") from e


def evaluate(expr, row=None, group=None):
    """Evaluate an Expr using a row mapping and optional aggregate group."""
    if expr is None:
        return None
    kind, value, args = expr.kind, expr.value, expr.args
    if kind == "literal":
        return value
    if kind == "column":
        return _column(row, value)
    if kind == "unary":
        v = evaluate(args[0], row, group)
        op = str(value).upper()
        if op == "NOT":
            t = _truth(v)
            return None if t is None else not t
        if v is None:
            return None
        if op == "-" and _numeric(v):
            return -v
        raise QueryError("unary minus requires a numeric value")
    if kind == "binary":
        op = str(value).upper()
        a = evaluate(args[0], row, group)
        if op in ("AND", "OR"):
            a = _truth(a)
            if op == "AND" and a is False:
                return False
            if op == "OR" and a is True:
                return True
            b = _truth(evaluate(args[1], row, group))
            if op == "AND":
                if b is False: return False
                return None if a is None or b is None else True
            if b is True: return True
            return None if a is None or b is None else False
        b = evaluate(args[1], row, group)
        if op in ("+", "-", "*", "/", "||"):
            return _arithmetic(op, a, b)
        if a is None or b is None:
            return None
        return _cmp(a, b, op)
    if kind == "is_null":
        result = evaluate(args[0], row, group) is None
        return not result if value else result
    if kind == "in":
        x, saw_null, matched = evaluate(args[0], row, group), False, False
        saw_null = x is None
        for arg in args[1:]:
            y = evaluate(arg, row, group)
            if y is None:
                saw_null = True
            elif x is not None and _cmp(x, y, "="):
                matched = True
                break
        result = True if matched else None if saw_null else False
        return _not3(result) if value else result
    if kind == "between":
        x, low, high = (evaluate(a, row, group) for a in args)
        left = None if x is None or low is None else _cmp(low, x, "<=")
        right = None if x is None or high is None else _cmp(x, high, "<=")
        result = _and3(left, right)
        return _not3(result) if value else result
    if kind == "like":
        x, pattern = (evaluate(a, row, group) for a in args)
        if x is None or pattern is None:
            result = None
        elif not isinstance(x, str) or not isinstance(pattern, str):
            raise QueryError("LIKE requires strings")
        else:
            regex = "\\A" + "".join(".*" if c == "%" else "." if c == "_" else re.escape(c) for c in pattern) + "\\Z"
            result = re.match(regex, x, re.DOTALL) is not None
        return _not3(result) if value else result
    if kind == "call":
        name = str(value).upper()
        if name in AGGREGATES:
            return _aggregate(name, args, group)
        if name == "COALESCE":
            if not args: raise QueryError("COALESCE requires at least one argument")
            for arg in args:
                v = evaluate(arg, row, group)
                if v is not None: return v
            return None
        values = [evaluate(a, row, group) for a in args]
        if name == "ROUND":
            if len(values) not in (1, 2): raise QueryError("ROUND requires one or two arguments")
            if any(v is None for v in values): return None
            n = 0 if len(values) == 1 else values[1]
            if not isinstance(n, int) or isinstance(n, bool): raise QueryError("ROUND precision must be an integer")
            return _round_away(values[0], n)
        if name not in ("LOWER", "UPPER", "LENGTH", "ABS"):
            raise QueryError("unknown function: " + str(value))
        if len(values) != 1: raise QueryError(name + " requires one argument")
        x = values[0]
        if x is None: return None
        if name in ("LOWER", "UPPER", "LENGTH"):
            if not isinstance(x, str): raise QueryError(name + " requires a string")
            return x.lower() if name == "LOWER" else x.upper() if name == "UPPER" else len(x)
        if not _numeric(x): raise QueryError("ABS requires a numeric value")
        return abs(x)
    raise QueryError("invalid expression")


def _not3(v):
    return None if v is None else not v


def _and3(a, b):
    if a is False or b is False: return False
    if a is None or b is None: return None
    return True


def _aggregate(name, args, group):
    if group is None:
        raise QueryError("aggregate used outside a grouped query")
    if len(args) != 1:
        raise QueryError(name + " requires one argument")
    arg = args[0]
    if name == "COUNT" and arg.__class__.__name__ == "Star":
        return len(group)
    vals = []
    for row in group:
        v = evaluate(arg, row, None)
        if v is not None: vals.append(v)
    if name == "COUNT": return len(vals)
    if not vals: return None
    if name in ("SUM", "AVG"):
        if any(not _numeric(v) for v in vals): raise QueryError(name + " requires numeric values")
        return sum(vals) if name == "SUM" else float(sum(vals)) / len(vals)
    result = vals[0]
    for v in vals[1:]:
        _compare_type(result, v)
        if name == "MIN" and v < result or name == "MAX" and v > result:
            result = v
    return result

"""Run SQL SELECT queries against CSV files. See SPEC.md."""

class QueryError(Exception):
    """Raised for any problem with a query."""


from .io import load_table
from .parser import parse, ParseError
from .evaluator import evaluate, contains_aggregate, validate_aggregates


def run(sql, directory="."):
    """Run ``sql`` against the CSV files in ``directory``."""
    try:
        query = parse(sql)
    except ParseError as e:
        raise QueryError(str(e)) from e
    headers, source_rows = load_table(query.table, directory)
    # A row mapping retains the source spelling while evaluator performs
    # case-insensitive lookup.
    rows = [dict(zip(headers, values)) for values in source_rows]

    def has_agg(expr):
        return expr is not None and contains_aggregate(expr)

    grouped = bool(query.group_by) or any(
        has_agg(item.expr) for item in query.columns if hasattr(item, "expr")
    ) or has_agg(query.having) or any(has_agg(item.expr) for item in query.order_by)

    # Expand * before validation and evaluation.
    from .parser import Expr, SelectItem, Star
    items = []
    for item in query.columns:
        if item is Star or isinstance(item, Star):
            items.extend(SelectItem(Expr("column", h, raw=h), None) for h in headers)
        else:
            items.append(item)

    def check_group_expr(expr):
        if expr is None:
            return
        if expr.kind == "call" and str(expr.value).upper() in {"COUNT", "SUM", "AVG", "MIN", "MAX"}:
            return
        if expr in query.group_by:
            return
        if expr.kind == "column":
            raise QueryError("column must appear in GROUP BY or an aggregate")
        for child in expr.args:
            if isinstance(child, Expr):
                check_group_expr(child)

    for item in items:
        validate_aggregates(item.expr)
        if grouped:
            check_group_expr(item.expr)
    validate_aggregates(query.where, allow=False)
    validate_aggregates(query.having)
    if grouped and query.having is not None:
        check_group_expr(query.having)
    for order in query.order_by:
        validate_aggregates(order.expr)
        if grouped:
            check_group_expr(order.expr)

    filtered = [r for r in rows if query.where is None or evaluate(query.where, r) is True]
    groups = []
    if grouped:
        if query.group_by:
            indexed = {}
            for r in filtered:
                key = tuple(evaluate(e, r) for e in query.group_by)
                try:
                    bucket = indexed.get(key)
                except TypeError:
                    key = tuple(_freeze(v) for v in key)
                    bucket = indexed.get(key)
                if bucket is None:
                    bucket = (key, [])
                    indexed[key] = bucket
                    groups.append(bucket[1])
                bucket[1].append(r)
        else:
            groups = [filtered]
    else:
        groups = [[r] for r in filtered]

    results = []
    for group in groups:
        representative = group[0] if group else {}
        if query.having is not None and evaluate(query.having, representative, group) is not True:
            continue
        out = tuple(evaluate(i.expr, representative, group if grouped else None) for i in items)
        order_keys = []
        for oi in query.order_by:
            expr = oi.expr
            value = None
            if expr.kind == "literal" and isinstance(expr.value, int) and not isinstance(expr.value, bool):
                n = expr.value
                if 1 <= n <= len(out):
                    value = out[n - 1]
                else:
                    raise QueryError("ORDER BY column number is out of range")
            elif expr.kind == "column":
                name = str(expr.value).casefold()
                match = next((j for j, i in enumerate(items) if (i.alias or (i.expr.value if i.expr.kind == "column" else i.expr.raw)).casefold() == name), None)
                if match is not None:
                    value = out[match]
                else:
                    value = evaluate(expr, representative, group if grouped else None)
            else:
                value = evaluate(expr, representative, group if grouped else None)
            order_keys.append(value)
        results.append([out, order_keys])

    # Stable multi-key sort, handling NULL placement and mixed permitted types.
    for k in range(len(query.order_by) - 1, -1, -1):
        desc = query.order_by[k].descending
        def keyfun(record, k=k):
            v = record[1][k]
            if v is None:
                return (0 if desc else 0, 0, 0)
            if isinstance(v, bool):
                typ, val = 1, int(v)
            elif isinstance(v, (int, float)):
                typ, val = 1, v
            elif isinstance(v, str):
                typ, val = 2, v
            else:
                raise QueryError("values are not mutually comparable")
            return (1, typ, val)
        # Separate NULLs to keep them first ascending and last descending.
        nulls = [r for r in results if r[1][k] is None]
        vals = [r for r in results if r[1][k] is not None]
        try:
            vals.sort(key=lambda rec: keyfun(rec), reverse=desc)
        except TypeError as e:
            raise QueryError("values are not mutually comparable") from e
        results = vals + nulls if desc else nulls + vals

    if query.distinct:
        unique = []
        seen = set()
        for record in results:
            k = tuple(_freeze(v) for v in record[0])
            if k not in seen:
                seen.add(k)
                unique.append(record)
        results = unique
    start = query.offset or 0
    if query.limit is not None:
        results = results[start:start + query.limit]
    elif start:
        results = results[start:]
    names = []
    for item in items:
        if item.alias:
            names.append(item.alias)
        elif item.expr.kind == "column":
            header = next((h for h in headers if h.casefold() == str(item.expr.value).casefold()), str(item.expr.value))
            names.append(header)
        else:
            names.append(item.expr.raw)
    return Result(names, [r[0] for r in results])


class Result:
    def __init__(self, columns, rows):
        self.columns = columns
        self.rows = rows


def _freeze(value):
    if isinstance(value, list):
        return tuple(_freeze(v) for v in value)
    if isinstance(value, dict):
        return tuple(sorted((k, _freeze(v)) for k, v in value.items()))
    return value

"""CSV table loading helpers for minisql."""

import csv
import os
import re


_INTEGER = re.compile(r"-?[0-9]+\Z")
_DECIMAL = re.compile(r"(?:-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+)\Z")


def _convert(value):
    if value == "":
        return None
    if _INTEGER.fullmatch(value):
        return int(value)
    if _DECIMAL.fullmatch(value):
        return float(value)
    return value


def load_table(name, directory="."):
    """Load ``name.csv`` and return ``(column_names, tuple_rows)``.

    Values are converted according to the CSV rules in SPEC.md. All input
    errors are surfaced as QueryError so callers need only handle one public
    error type.
    """
    from . import QueryError

    path = os.path.join(os.fspath(directory), f"{name}.csv")
    try:
        with open(path, "r", encoding="utf-8-sig", newline="") as stream:
            reader = csv.reader(stream)
            try:
                header = next(reader)
            except StopIteration:
                raise QueryError(f"table {name!r} has no header")

            if not header or any(column == "" for column in header):
                raise QueryError(f"table {name!r} has an invalid header")
            folded = [column.casefold() for column in header]
            if len(set(folded)) != len(folded):
                raise QueryError(f"table {name!r} has duplicate column names")

            rows = []
            for line_number, fields in enumerate(reader, start=2):
                if len(fields) != len(header):
                    raise QueryError(
                        f"table {name!r} row {line_number} has {len(fields)} "
                        f"fields; expected {len(header)}"
                    )
                rows.append(tuple(_convert(field) for field in fields))
            return header, rows
    except QueryError:
        raise
    except (OSError, UnicodeError, csv.Error) as exc:
        raise QueryError(f"could not read table {name!r}: {exc}") from exc

"""Command line entry point for minisql."""

import argparse
import csv
import sys

from . import QueryError, run


def _csv_value(value):
    if value is None:
        return ""
    if value is True:
        return "true"
    if value is False:
        return "false"
    return value


def main(argv=None):
    parser = argparse.ArgumentParser(prog="python -m minisql")
    parser.add_argument("query", help="SQL SELECT query to execute")
    parser.add_argument("--dir", default=".", help="directory containing CSV tables")
    args = parser.parse_args(argv)

    try:
        result = run(args.query, args.dir)
    except QueryError as exc:
        print(str(exc), file=sys.stderr)
        return 1

    writer = csv.writer(sys.stdout)
    writer.writerow(result.columns)
    writer.writerows(tuple(_csv_value(value) for value in row) for row in result.rows)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
